'use strict';
// exploration build|check: the exploration guides (guides/forever/exploration),
// generated by tools/lib/exploration/build.js.

const path = require('node:path');
const { parseArgs } = require('node:util');
const { reportSync } = require('../lib/generated');

const usage = `usage: node tools/polestar.js exploration build [options]
       node tools/polestar.js exploration check [options]

build: rewrites guides/forever/exploration/*.guide, one guide per continent
and level range plus Zephras Isle, from the Forever client's map tables
(wago.tools CSV, cached in <sources>/wago), data/forever (zones, map frames,
flight masters from travel.json) and the zone order in
tools/lib/exploration/spec.js. Run \`compile\` afterwards.

check: builds the same guides in memory and exits 1 when a committed guide
differs (writes nothing).

  --offline            use cached tables only
  --build <version>    wago.tools build (default: newest listed)
  --data <dir>         reference data (default data/forever)
  --sources <dir>      source cache (default data/sources)
  --stdout             print the guides instead of writing them (build only)`;

function fail(msg) {
	console.error(`${msg}\n\n${usage}`);
	return 2;
}

async function run(argv) {
	let values;
	let positionals;
	try {
		({ values, positionals } = parseArgs({
			args: argv,
			options: { offline: { type: 'boolean' }, build: { type: 'string' }, data: { type: 'string' }, sources: { type: 'string' }, stdout: { type: 'boolean' } },
			allowPositionals: true,
			strict: true,
		}));
	} catch (err) {
		return fail(err.message);
	}
	const [sub, ...extra] = positionals;
	if (sub !== 'build' && sub !== 'check') return fail(sub ? `unknown subcommand "${sub}"` : 'missing subcommand');
	if (extra.length) return fail(`unexpected argument "${extra[0]}"`);
	if (values.stdout && sub === 'check') return fail('--stdout goes with build');
	const { buildAll, OUT_DIR } = require('../lib/exploration/build');
	const abs = (p) => (p ? path.resolve(p) : undefined);
	const res = await buildAll({ dataDir: abs(values.data), sourcesDir: abs(values.sources), offline: values.offline, build: values.build, log: (m) => console.error(m) });
	for (const w of res.warnings) console.error(`warning: ${w}`);
	console.error(`Forever build ${res.build}: ${Object.entries(res.counts).map(([c, n]) => `${c} ${n} areas`).join(', ')}`);
	if (values.stdout) {
		for (const [name, text] of Object.entries(res.files)) process.stdout.write(`==> ${name}\n${text}\n`);
		return 0;
	}
	return reportSync(res.files, OUT_DIR, { check: sub === 'check', command: 'exploration build' });
}

module.exports = { name: 'exploration', summary: 'Build or check the generated exploration guides', usage, run };
